/**
 * Generate PR comment for Socket Security dependency analysis
 *
 * This script calls the Anthropic API to generate a formatted PR comment
 * based on Socket Security package scores. Falls back to basic formatting
 * if the API call fails.
 */

const https = require('https');
const fs = require('fs');
const path = require('path');

module.exports = async ({ github, context, core }, packages) => {
  const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY;
  const MAX_COMMENT_LENGTH = 65000;

  // Load prompt template
  const promptTemplatePath = path.join(__dirname, '..', 'prompts', 'socket-pr-comment.md');
  let promptTemplate = '';
  try {
    promptTemplate = fs.readFileSync(promptTemplatePath, 'utf8');
  } catch (e) {
    console.log('Warning: Could not load prompt template, using fallback');
  }

  const inputData = {
    packages: packages,
    prNumber: context.payload.pull_request?.number,
    commitSha: context.payload.pull_request?.head?.sha?.substring(0, 7),
    timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19) + ' UTC'
  };

  // Try Claude API first
  if (ANTHROPIC_API_KEY && promptTemplate) {
    try {
      const claudeResponse = await callClaudeAPI(ANTHROPIC_API_KEY, promptTemplate, inputData);
      if (claudeResponse) {
        let body = claudeResponse;
        if (body.length > MAX_COMMENT_LENGTH) {
          body = body.substring(0, MAX_COMMENT_LENGTH - 100) + '\n\n*Comment truncated for length.*\n';
        }
        core.setOutput('body', body);
        return body;
      }
    } catch (e) {
      console.log(`Claude API error: ${e.message}. Falling back to basic formatting.`);
    }
  } else {
    console.log('No ANTHROPIC_API_KEY or prompt template, using fallback formatting.');
  }

  // Fallback: Generate basic comment without Claude
  const fallbackBody = generateFallbackComment(packages, context);
  core.setOutput('body', fallbackBody);
  return fallbackBody;
};

async function callClaudeAPI(apiKey, promptTemplate, inputData) {
  const prompt = `${promptTemplate}

---

## Input Data

\`\`\`json
${JSON.stringify(inputData, null, 2)}
\`\`\`

---

Generate the PR comment now. Output ONLY the markdown comment, nothing else.`;

  const requestBody = JSON.stringify({
    model: 'claude-sonnet-4-20250514',
    max_tokens: 4000,
    messages: [
      {
        role: 'user',
        content: prompt
      }
    ]
  });

  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'Content-Length': Buffer.byteLength(requestBody)
      },
      timeout: 60000
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode !== 200) {
          reject(new Error(`API returned ${res.statusCode}: ${data}`));
          return;
        }
        try {
          const response = JSON.parse(data);
          const text = response.content?.[0]?.text || '';
          resolve(text);
        } catch (e) {
          reject(new Error(`Failed to parse response: ${e.message}`));
        }
      });
    });

    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.write(requestBody);
    req.end();
  });
}

function generateFallbackComment(packages, context) {
  let body = '# Dependency Analysis\n\n';

  if (packages.length === 0) {
    body += '> No dependency changes detected by Socket Security.\n\n';
    body += '<sub>Generated by Swoogy Dependency Analyzer</sub>\n';
    return body;
  }

  // Determine overall status
  const hasLowScores = packages.some(p => {
    const scores = Object.values(p.scores).filter(s => s !== null);
    return scores.some(s => s < 50);
  });

  if (hasLowScores) {
    body += '> \u26A0\uFE0F **Needs Review** \u2014 Some packages have low scores that warrant attention.\n\n';
  } else {
    body += '> \u2705 **All Clear** \u2014 All dependency changes look healthy.\n\n';
  }

  body += `This PR changes ${packages.length} package${packages.length !== 1 ? 's' : ''}. `;
  body += 'Here are the Socket Security scores for each.\n\n';

  // Score table
  body += '| Package | Version | Supply Chain | Vulnerability | Quality | Maintenance | License |\n';
  body += '|---------|---------|:---:|:---:|:---:|:---:|:---:|\n';

  for (const pkg of packages) {
    const s = pkg.scores;
    body += `| \`${pkg.name}\` | ${pkg.version} `;
    body += `| ${formatScore(s.supplyChain)} `;
    body += `| ${formatScore(s.vulnerability)} `;
    body += `| ${formatScore(s.quality)} `;
    body += `| ${formatScore(s.maintenance)} `;
    body += `| ${formatScore(s.license)} |\n`;
  }

  body += '\n### Score Categories\n\n';
  body += '- **Supply Chain**: How well the package protects against supply chain attacks (typosquatting, maintainer hijacking)\n';
  body += '- **Vulnerability**: Known CVEs and security advisories affecting this package\n';
  body += '- **Quality**: Code quality signals like test coverage, documentation, and error handling\n';
  body += '- **Maintenance**: How actively the package is maintained (recent commits, issue response time)\n';
  body += '- **License**: License compatibility and clarity\n\n';

  body += '---\n\n';
  body += 'Questions? Ask **@platform-team** in Slack\n\n';
  body += '<sub>Generated by Swoogy Dependency Analyzer</sub>\n';

  return body;
}

function formatScore(score) {
  if (score === null || score === undefined) return '-';
  if (score >= 80) return `\u2705 ${score}`;
  if (score >= 50) return `\u26A0\uFE0F ${score}`;
  return `\u274C ${score}`;
}
